choose.when:
SELECT COUNT(1)
FROM rec_user_recommendation r
INNER JOIN sys_huagao h ON h.id = r.item_id
WHERE r.domain = #{domain}
  AND r.model_version = #{modelVersion}
  AND r.actor_key = #{actorKey}
  AND h.status = '审核成功'
  AND h.type = '上架'

SELECT COUNT(1)
FROM rec_user_recommendation r
INNER JOIN sys_zuopin z ON z.id = r.item_id
WHERE r.domain = #{domain}
  AND r.model_version = #{modelVersion}
  AND r.actor_key = #{actorKey}

SELECT COUNT(1)
FROM rec_user_recommendation r
INNER JOIN sys_project p ON p.id = r.item_id
WHERE r.domain = #{domain}
  AND r.model_version = #{modelVersion}
  AND r.actor_key = #{actorKey}
  AND p.status = '招募中'

choose.otherwise:
SELECT COUNT(1)
FROM rec_user_recommendation r
INNER JOIN x_user u ON u.id = r.item_id
WHERE r.domain = #{domain}
  AND r.model_version = #{modelVersion}
  AND r.actor_key = #{actorKey}
  AND u.status = 1
  AND COALESCE(u.deleted, 0) = 0
